#include "stdlib/stats/base/dists/f/quantile.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/special/kernel_betaincinv.h"

/**
* Evaluates the quantile function for an F distribution with numerator degrees of freedom `d1` and denominator degrees of freedom `d2` at a probability `p`.
*
* @param p    input probability
* @param d1   numerator degrees of freedom
* @param d2   denominator degrees of freedom
* @return     evaluated quantile function
*
* @example
* double y = stdlib_base_dists_f_quantile( 0.8, 1.0, 1.0 );
* // returns ~9.472
*/
double stdlib_base_dists_f_quantile( const double p, const double d1, const double d2 ) {
	double x;
	double y;
	if (
		stdlib_base_is_nan( p ) ||
		stdlib_base_is_nan( d1 ) ||
		stdlib_base_is_nan( d2 ) ||
		d1 <= 0.0 ||
		d2 <= 0.0 ||
		p < 0.0 ||
		p > 1.0
	) {
		return 0.0/0.0; // NaN
	}
	stdlib_base_kernel_betaincinv( d1 / 2.0, d2 / 2.0, p, 1.0 - p, &x, &y );
	return d2 * x / ( d1 * y );
}
